parameters.jsCode:
const raw = $input.item.json.candidates?.[0]?.content?.parts?.[0]?.text
  || $input.item.json.choices?.[0]?.message?.content || '{}';

let est;
try { est = JSON.parse(raw); }
catch(e) {
  const m = raw.match(/\{[\s\S]*\}/);
  try { est = m ? JSON.parse(m[0]) : {}; } catch(e2) { est = {}; }
}

const ctx = $('🔧 Preparar Contexto').item.json;

return [{ json: {
  company_id:          Number(ctx.company_id) || 1,
  // Campos del modal G54
  objetivo:            est.objetivo             || ctx.objetivo  || '',
  audiencia:           est.audiencia            || ctx.audiencia || '',
  tono:                est.tono                 || 'profesional y directo',
  frecuencia:          est.frecuencia           || '',
  director_cta:        est.director_cta         || ctx.web       || '',
  embudo:              est.embudo               || '',
  plataformas:         est.plataformas          || '',
  pilares:             est.pilares              || '',
  kpis:                est.kpis                 || '',
  // Campos extendidos
  resumen_estrategico: est.resumen_estrategico  || '',
  keyword_strategy:    est.keyword_strategy     || {},
  mapa_preguntas_aeo:  est.mapa_preguntas_aeo   || [],
  faqs:                est.faqs                 || [],
  clusters:            est.clusters             || [],
  plan_publicacion:    est.plan_publicacion     || {},
  ideas_plan:          est.ideas_plan           || [],
  // Meta
  empresa_nombre:      ctx.empresa_nombre,
  email:               ctx.email,
  tiempo_horizonte:    ctx.tiempo_horizonte,
  total_ideas:         ctx.total_ideas,
  ideas_generadas:     (est.ideas_plan||[]).length
} }];

parameters.message:
={{ (() => {
  const e = $('🔍 Parsear Estrategia').item.json;
  const ideas = (e.ideas_plan||[]).length;
  return '<h2>🧠 Estrategia G54 lista — ' + e.empresa_nombre + '</h2>'
    + '<p><strong>Horizonte:</strong> ' + (e.tiempo_horizonte||'') + ' · <strong>Posts planificados:</strong> ' + ideas + ' de ' + (e.total_ideas||0) + ' esperados</p>'
    + '<h3>Resumen estratégico</h3><p>' + e.resumen_estrategico + '</p>'
    + '<h3>Frecuencia</h3><p>' + e.frecuencia + '</p>'
    + '<h3>Plataformas</h3><p>' + e.plataformas + '</p>'
    + '<h3>Pilares</h3><p>' + e.pilares + '</p>'
    + '<h3>Keywords principales</h3><p>' + (e.keyword_strategy?.principales||[]).join(', ') + '</p>'
    + '<h3>FAQs del nicho</h3><ul>' + (e.faqs||[]).map(f=>'<li>'+f+'</li>').join('') + '</ul>'
    + '<p><em>Estrategia guardada en G54. El Content AI la usará en la próxima ejecución.</em></p>';
})() }}
